import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"32、【恆】 巽下震上","description":"橫渠易說 - 32、【恆】 巽下震上","frontmatter":{"title":"32、【恆】 巽下震上","description":"橫渠易說 - 32、【恆】 巽下震上"},"headers":[],"relativePath":"classics/hengqu/034.md","filePath":"classics/hengqu/034.md"}'),l={name:"classics/hengqu/034.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_32、【恆】-巽下震上" tabindex="-1">32、【恆】 巽下震上 <a class="header-anchor" href="#_32、【恆】-巽下震上" aria-label="Permalink to “32、【恆】 巽下震上”">​</a></h1><h3 id="彖曰-恆-久也-剛上而柔下-雷風相與-巽而動-剛柔皆應-恆。-恆亨無咎利貞-久於其道也-天地之道恆久而不已也。-利有攸往-終則有始也。日月得天而能久照-四時變化而能久成-聖人久於其道而天下化成-觀其所恆而天地萬物之情可見矣。" tabindex="-1">彖曰：恆，久也，剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。“恆亨無咎利貞”，久於其道也，天地之道恆久而不已也。“利有攸往”，終則有始也。日月得天而能久照，四時變化而能久成，聖人久於其道而天下化成，觀其所恆而天地萬物之情可見矣。 <a class="header-anchor" href="#彖曰-恆-久也-剛上而柔下-雷風相與-巽而動-剛柔皆應-恆。-恆亨無咎利貞-久於其道也-天地之道恆久而不已也。-利有攸往-終則有始也。日月得天而能久照-四時變化而能久成-聖人久於其道而天下化成-觀其所恆而天地萬物之情可見矣。" aria-label="Permalink to “彖曰：恆，久也，剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。“恆亨無咎利貞”，久於其道也，天地之道恆久而不已也。“利有攸往”，終則有始也。日月得天而能久照，四時變化而能久成，聖人久於其道而天下化成，觀其所恆而天地萬物之情可見矣。”">​</a></h3><h3 id="象曰-雷風恆-君子以立不易方。" tabindex="-1">象曰：雷風恆，君子以立不易方。 <a class="header-anchor" href="#象曰-雷風恆-君子以立不易方。" aria-label="Permalink to “象曰：雷風恆，君子以立不易方。”">​</a></h3><p>觀書當不以文害辭，如雲義者出於思慮忖度，易言“天地之大義”，則天地固無思慮。“天地之情”“天地之心”皆放此。</p><h3 id="初六-浚恆-貞兇-無攸利。-象曰-浚恆之兇-始求深也。" tabindex="-1">初六，浚恆，貞兇，無攸利。 象曰：浚恆之兇，始求深也。 <a class="header-anchor" href="#初六-浚恆-貞兇-無攸利。-象曰-浚恆之兇-始求深也。" aria-label="Permalink to “初六，浚恆，貞兇，無攸利。 象曰：浚恆之兇，始求深也。”">​</a></h3><p>柔巽在下以應於上，持用為常，求之過深也。故人道之交貴乎中禮，且久漸而成也。持一作特。</p><h3 id="九二-悔亡。-象曰-九二悔亡-能久中也。" tabindex="-1">九二，悔亡。 象曰：“九二悔亡”，能久中也。 <a class="header-anchor" href="#九二-悔亡。-象曰-九二悔亡-能久中也。" aria-label="Permalink to “九二，悔亡。 象曰：“九二悔亡”，能久中也。”">​</a></h3><p>以陽系陰，用以為常，不能無悔，以其久中故免。</p><h3 id="九三-不恆其德-或承之羞-貞吝。-象曰-不恆其德-無所容也。" tabindex="-1">九三，不恆其德，或承之羞，貞吝。 象曰：“不恆其德”，無所容也。 <a class="header-anchor" href="#九三-不恆其德-或承之羞-貞吝。-象曰-不恆其德-無所容也。" aria-label="Permalink to “九三，不恆其德，或承之羞，貞吝。 象曰：“不恆其德”，無所容也。”">​</a></h3><p>進則犯上，退則乘剛，故動則招悔取辱，惟常守一德，庶幾取容，故曰不恆其德則無所容也。一有“雖然貞吝，德則可常也”。</p><h3 id="九四-田無禽。-象曰-久非其位-安得禽也" tabindex="-1">九四，田無禽。 象曰：久非其位，安得禽也! <a class="header-anchor" href="#九四-田無禽。-象曰-久非其位-安得禽也" aria-label="Permalink to “九四，田無禽。 象曰：久非其位，安得禽也!”">​</a></h3><p>田以時至則禽或可得，處常非位則功無以致，故君子降志辱身，不可常也。</p><h3 id="六五-恆其德貞-婦人吉-夫子兇。-象曰-婦人貞吉-從一而終也-夫子制義-從婦兇也。" tabindex="-1">六五，恆其德貞，婦人吉，夫子兇。 象曰：婦人貞吉，從一而終也；夫子制義，從婦兇也。 <a class="header-anchor" href="#六五-恆其德貞-婦人吉-夫子兇。-象曰-婦人貞吉-從一而終也-夫子制義-從婦兇也。" aria-label="Permalink to “六五，恆其德貞，婦人吉，夫子兇。 象曰：婦人貞吉，從一而終也；夫子制義，從婦兇也。”">​</a></h3><h3 id="上六-振恆-兇。-象曰-振恆在上-大無功也。" tabindex="-1">上六，振恆，兇。 象曰：振恆在上，大無功也。 <a class="header-anchor" href="#上六-振恆-兇。-象曰-振恆在上-大無功也。" aria-label="Permalink to “上六，振恆，兇。 象曰：振恆在上，大無功也。”">​</a></h3><p>卦例於上爻多處之以貴而無位，高而無民，至恆又不可以此處，但見其不常在上，故大無功也。 易道灼然義理分明，自存乎卦，惟要人玩之乃得。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
